import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { CopyButton } from "@/registry/erbium/blocks/copy-button";
export default function Demo() {
  return (
    <div className="flex items-center gap-3">
      <code className="text-sm">Erbium UI</code>
      <CopyButton value="Erbium UI" aria-label="Copy project name" variant="outline" />
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from "../examples/use-copy-to-clipboard-demo";

const Example = () => <Demo />;

export default Example;
";

const meta = {
  parameters: {
    layout: "centered",
    docs: { description: { component: "## Recommended usage

Use `CopyButton` from `@/registry/erbium/blocks/copy-button` for a complete copy control. It combines this hook with the shared Button, animated CopyButtonIcon, and accessible success and failure announcements.

```tsx
<CopyButton value={command} aria-label="Copy installation command" />
```

Use its `render` prop to compose an existing button, including InputGroupButton. Default icons inherit their size from the surrounding button.

## Hook API

`CopyButton` owns the interaction, icon, labels, and announcements. Its underlying `useCopyToClipboard` hook is available from `@/registry/erbium/hooks/use-copy-to-clipboard` for integrations that need clipboard state beyond the control. Use the block for copy actions rather than rebuilding a button around the hook.

```tsx
const { copyToClipboard, isCopied, isPending, error } = useCopyToClipboard({
  timeout: 2000,
  onCopy: () => console.info("Copy completed"),
  onError: reportError,
});
```

`copyToClipboard(value)` returns a promise resolving to a success boolean. It prevents overlapping writes, accepts empty strings, and sets `isCopied` only after the write succeeds. `isPending` tracks the operation; `error` contains a failure. `status` is idle, copied, or error; `revision` increments after each completed attempt. Repeated attempts retain existing feedback while pending, then restart the feedback timer when they settle. A timeout of zero keeps success visible. Cleanup cancels timers and prevents late operation results from updating a disposed owner.

The block supplies an accessible name, animated stateful icon, and a live status region. Clipboard access requires a secure browser context. Unsupported access is reported through `error` and `onError`.

## Astro and plain JavaScript

A React hook requires React. Astro browser scripts use `createCopyToClipboard` from `@/registry/erbium/lib/copy-to-clipboard`, the same controller that powers this hook. There is one clipboard implementation shared by both adapters. Astro copy actions use the shared `CopyButton.astro` control; pages do not wire their own clipboard handlers or feedback.

The controller also accepts an async text resolver, allowing Astro to fetch Markdown within the same pending and error lifecycle. Content fetching stays with the adapter. The docs' Astro copy controls subscribe to this controller and dispose it on disconnect.

Registry installation of the hook includes the shared controller. Installing CopyButton includes both automatically." } },
  },
} satisfies Meta;

export default { ...meta, title: "Hooks/Use Copy To Clipboard",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj<typeof meta>;

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "Use CopyButton for ready-to-use copying with an animated icon and accessible feedback. It uses useCopyToClipboard internally and inherits icon sizing from its button." },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

import CustomButtonExample from "./variants/custom-button";
const CustomButtonSource = "import { CopyButton, CopyButtonIcon, CopyButtonLabel } from "@/registry/erbium/blocks/copy-button";
import { Button } from "@/registry/erbium/ui/button";
export default function Example() {
  return (
    <CopyButton value="Erbium UI" render={<Button size="sm" variant="outline" />}>
      <CopyButtonIcon data-icon="inline-start" />
      <CopyButtonLabel />
    </CopyButton>
  );
}
";

export const CustomButton: Story = {
  parameters: {
    docs: {
      description: { story: "Compose CopyButton with an existing Button through render. CopyButtonIcon and CopyButtonLabel share state automatically; labels have stable sizing, animations, failure feedback, and accessible announcements built in." },
      source: { code: CustomButtonSource },
    },
  },
  render: CustomButtonExample,
};

